public class FinallyReturnTrap {
    public static void main(String[] args) {
        System.out.println(getValue()); // Prints 20, completely ignoring the exception!
    }

    public static int getValue() {
        try {
            throw new NullPointerException("Original failure");
        } catch (Exception e) {
            return 10;
        } finally {
            return 20; // This return overrides everything
        }
    }
}
